import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class ReservationIT {
    private static String dbUrl;
    private static ObjectMapper objectMapper;

    @BeforeAll
    static void setup() throws Exception {
        dbUrl = "jdbc:postgresql://localhost:5432/pousada_test";
        String dbUser = "postgres";
        String dbPassword = "postgres";

        System.setProperty("DB_URL", dbUrl);
        System.setProperty("DB_USER", dbUser);
        System.setProperty("DB_PASSWORD", dbPassword);

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
             Statement stmt = conn.createStatement()) {
            stmt.execute("DROP TABLE IF EXISTS reservations CASCADE");
            stmt.execute("DROP TABLE IF EXISTS messages CASCADE");
            stmt.execute("DROP TABLE IF EXISTS rooms CASCADE");
        }

        objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JavaTimeModule());
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbUrl != null) {
            try (Connection conn = DriverManager.getConnection(
                    System.getProperty("DB_URL"),
                    System.getProperty("DB_USER"),
                    System.getProperty("DB_PASSWORD"));
                 Statement stmt = conn.createStatement()) {
                stmt.execute("DROP TABLE IF EXISTS reservations CASCADE");
                stmt.execute("DROP TABLE IF EXISTS messages CASCADE");
                stmt.execute("DROP TABLE IF EXISTS rooms CASCADE");
            }
        }
    }

    @Test
    void testBasicReservationFlow() throws IOException, InterruptedException {
        String[] args = {};
        Main.main(args);

        Thread.sleep(1000);

        HttpClient client = HttpClient.newHttpClient();

        String createBody = """
            {
                "roomNumber": "101",
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "12345678901",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpRequest createRequest = HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:7070/reservations"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(createBody))
                .build();

        HttpResponse<String> createResponse = client.send(createRequest, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, createResponse.statusCode());

        Map<String, Object> reservation = objectMapper.readValue(createResponse.body(), Map.class);
        assertEquals(1, reservation.get("id"));
        assertEquals("PENDING", reservation.get("status"));
        assertEquals(499.8, (Double) reservation.get("total"), 0.01);
    }
}

